const updateArticle = `-- name: UpdateArticle :one
UPDATE app.articles AS a SET
  type = $1, slug = $2, status = $3,
  category_id = (SELECT ac.id FROM app.article_categories ac WHERE ac.slug = $4::text),
  metal_id = (SELECT mm.id FROM market.metals mm WHERE mm.slug = $5::text),
  outlook = $6, featured = $7,
  title_fa = $8, title_en = $9,
  summary_fa = $10, summary_en = $11,
  keywords_fa = $12, keywords_en = $13,
  body_fa = $14, body_en = $15,
  author_fa = $16, author_en = $17,
  -- An uploaded picture owns cover_url (set by SetArticleImage), so a form sending an old value can't drop it.
  cover_url = CASE WHEN EXISTS (SELECT 1 FROM app.article_images ai WHERE ai.article_id = a.id) THEN a.cover_url ELSE $18 END,
  read_minutes = $19, video_url = $20,
  published_at = CASE
    WHEN $21::timestamptz IS NOT NULL THEN $21::timestamptz
    WHEN $3::text = 'published' THEN coalesce(a.published_at, now())
    ELSE a.published_at END,
  updated_by = $22
WHERE a.id = $23
RETURNING a.id
`

type UpdateArticleParams struct {
	Type         string
	Slug         string
	Status       string
	CategorySlug pgtype.Text
	MetalSlug    pgtype.Text
	Outlook      pgtype.Text
	Featured     bool
	TitleFa      string
	TitleEn      pgtype.Text
	SummaryFa    string
	SummaryEn    pgtype.Text
	KeywordsFa   string
	KeywordsEn   pgtype.Text
	BodyFa       string
	BodyEn       pgtype.Text
	AuthorFa     pgtype.Text
	AuthorEn     pgtype.Text
	CoverUrl     pgtype.Text
	ReadMinutes  int32
	VideoUrl     pgtype.Text
	PublishedAt  pgtype.Timestamptz
	Actor        pgtype.UUID
	ID           pgtype.UUID
}

// Publishing for the first time stamps published_at (unless one is given, e.g. a scheduled time).
func (q *Queries) UpdateArticle(ctx context.Context, arg UpdateArticleParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, updateArticle,
		arg.Type,
		arg.Slug,
		arg.Status,
		arg.CategorySlug,
		arg.MetalSlug,
		arg.Outlook,
		arg.Featured,
		arg.TitleFa,
		arg.TitleEn,
		arg.SummaryFa,
		arg.SummaryEn,
		arg.KeywordsFa,
		arg.KeywordsEn,
		arg.BodyFa,
		arg.BodyEn,
		arg.AuthorFa,
		arg.AuthorEn,
		arg.CoverUrl,
		arg.ReadMinutes,
		arg.VideoUrl,
		arg.PublishedAt,
		arg.Actor,
		arg.ID,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

